parameters.jsonBody:
={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What are current salary ranges for {{ $json.role }} with {{ $json.experience_years }} years experience in {{ $json.location }}? Include data from AmbitionBox, Glassdoor India, LinkedIn Salary, Naukri. Break down by company type: startup, mid-size, MNC. Include equity/bonus data if available."}],
  "search_recency_filter": "month"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What are current salaries for {{ $json.role }} with {{ $json.experience_years }} years experience in US, UK, UAE, Singapore, and Canada? Include total compensation breakdown. Sources: Levels.fyi, LinkedIn Salary, Glassdoor."}],
  "search_recency_filter": "month"
}

={
  "model": "sonar",
  "messages": [{"role": "user", "content": "What salary premium do specific skills command for {{ $json.role }} roles? Focus on: {{ $json.skills || 'AI/ML, Python, LLMs, cloud platforms' }}. What percentage salary increase does each skill add?"}],
  "search_recency_filter": "month"
}

parameters.text:
=Create a comprehensive salary benchmark report.

Role: {{ $('Set Benchmark Params').item.json.role }}
